#include "OfflineCatalog.hpp"
#include <cstdio>
#include <cerrno>
#include <cstring>
#include <mutex>
#include <set>
#define mutex recursive_mutex
#include <sys/stat.h>
#include <unistd.h>
namespace miyoofin { namespace {
constexpr unsigned V=1, MAX=100000, MAXS=1024*1024; std::recursive_mutex lock;
void u32(std::vector<unsigned char>&b,unsigned n){for(int i=0;i<4;i++)b.push_back(n>>(i*8));} void u64(std::vector<unsigned char>&b,unsigned long long n){for(int i=0;i<8;i++)b.push_back(n>>(i*8));}
bool r32(const std::vector<unsigned char>&b,size_t&p,unsigned&n){if(p+4>b.size())return false;n=0;for(int i=0;i<4;i++)n|=(unsigned)b[p++]<<(i*8);return true;} bool r64(const std::vector<unsigned char>&b,size_t&p,unsigned long long&n){if(p+8>b.size())return false;n=0;for(int i=0;i<8;i++)n|=(unsigned long long)b[p++]<<(i*8);return true;}
void str(std::vector<unsigned char>&b,const std::string&s){u32(b,s.size());b.insert(b.end(),s.begin(),s.end());} bool rst(const std::vector<unsigned char>&b,size_t&p,std::string&s){unsigned n;return r32(b,p,n)&&n<=MAXS&&p+n<=b.size()?(s.assign((const char*)&b[p],n),p+=n,true):false;}
void item(std::vector<unsigned char>&b,const MediaItem&i){str(b,i.id);str(b,i.title);str(b,i.overview);u32(b,i.year);unsigned x;memcpy(&x,&i.rating,4);u32(b,x);str(b,i.genre);str(b,i.type);str(b,i.etag);u32(b,i.played);memcpy(&x,&i.progress,4);u32(b,x);u64(b,i.playbackPositionTicks);u32(b,i.genres.size());for(auto&s:i.genres)str(b,s);u32(b,i.imageTags.size());for(auto&a:i.imageTags){str(b,a.first);str(b,a.second);}u32(b,i.indexNumber);u32(b,i.parentIndexNumber);u64(b,i.runTimeTicks);str(b,i.seriesName);str(b,i.seriesId);str(b,i.seasonId);b.push_back(i.artR);b.push_back(i.artG);b.push_back(i.artB);}
bool rit(const std::vector<unsigned char>&b,size_t&p,MediaItem&i){unsigned n,x;unsigned long long q;if(!rst(b,p,i.id)||!rst(b,p,i.title)||!rst(b,p,i.overview)||!r32(b,p,n)||!r32(b,p,x)||!rst(b,p,i.genre)||!rst(b,p,i.type)||!rst(b,p,i.etag))return false;i.year=n;memcpy(&i.rating,&x,4);if(!r32(b,p,n)||!r32(b,p,x)||!r64(b,p,q))return false;i.played=n;memcpy(&i.progress,&x,4);i.playbackPositionTicks=q;if(!r32(b,p,n)||n>MAX)return false;for(;n--;){std::string s;if(!rst(b,p,s))return false;i.genres.push_back(s);}if(!r32(b,p,n)||n>MAX)return false;for(;n--;){std::string a,c;if(!rst(b,p,a)||!rst(b,p,c))return false;i.imageTags[a]=c;}if(!r32(b,p,n)||!r32(b,p,x)||!r64(b,p,q)||!rst(b,p,i.seriesName)||!rst(b,p,i.seriesId)||!rst(b,p,i.seasonId)||p+3>b.size())return false;i.indexNumber=n;i.parentIndexNumber=x;i.runTimeTicks=q;i.artR=b[p++];i.artG=b[p++];i.artB=b[p++];return true;}
bool dirs(const std::string&p){for(size_t i=1;i<=p.size();i++)if(i==p.size()||p[i]=='/'){auto d=p.substr(0,i);if(!d.empty()&&mkdir(d.c_str(),0755)&&errno!=EEXIST)return false;}return true;}
void list(std::vector<unsigned char>&b,const std::map<std::string,std::vector<MediaItem> >&m){u32(b,m.size());for(auto&a:m){str(b,a.first);u32(b,a.second.size());for(auto&i:a.second)item(b,i);}} bool rlist(const std::vector<unsigned char>&b,size_t&p,std::map<std::string,std::vector<MediaItem> >&m){unsigned n;if(!r32(b,p,n)||n>MAX)return false;while(n--){std::string k;unsigned z;if(!rst(b,p,k)||!r32(b,p,z)||z>MAX)return false;auto&v=m[k];while(z--){MediaItem i;if(!rit(b,p,i))return false;v.push_back(std::move(i));}}return true;}
void mergeItems(std::vector<MediaItem>&into,const std::vector<MediaItem>&from){for(const auto&i:from){if(i.id.empty())continue;bool found=false;for(auto&old:into)if(old.id==i.id){old=i;found=true;break;}if(!found)into.push_back(i);}}
bool loadForUpdate(const std::string&p,OfflineCatalogSnapshot&x,std::string*e){if(OfflineCatalog::load(p,x,e))return true;return e&&*e=="not found";}
}
std::string OfflineCatalog::cachePath(const std::string&r,const std::string&s){return r+"/offline/"+s+"/catalog.v1";}
bool OfflineCatalog::save(const std::string&p,const OfflineCatalogSnapshot&s,std::string*e){std::lock_guard<std::mutex>g(lock);auto q=p.find_last_of('/');if(q!=std::string::npos&&!dirs(p.substr(0,q))){if(e)*e="mkdir failed";return false;}std::vector<unsigned char>b={'M','F','O','C'};u32(b,V);u32(b,s.series.size());for(auto&a:s.series){str(b,a.first);item(b,a.second);}list(b,s.seasonsBySeries);list(b,s.episodesBySeason);std::string t=p+".tmp."+std::to_string((long long)getpid());FILE*f=fopen(t.c_str(),"wb");bool ok=f&&fwrite(b.data(),1,b.size(),f)==b.size()&&fflush(f)==0&&fsync(fileno(f))==0&&fclose(f)==0;if(!ok||rename(t.c_str(),p.c_str())){if(f)fclose(f);remove(t.c_str());if(e)*e="write failed";return false;}return true;}
bool OfflineCatalog::load(const std::string&p,OfflineCatalogSnapshot&o,std::string*e){FILE*f=fopen(p.c_str(),"rb");if(!f){if(e)*e="not found";return false;}fseek(f,0,SEEK_END);long z=ftell(f);fseek(f,0,SEEK_SET);if(z<8||z>128*1024*1024){fclose(f);if(e)*e="invalid size";return false;}std::vector<unsigned char>b(z);bool ok=fread(b.data(),1,b.size(),f)==b.size();fclose(f);size_t x=4;unsigned v,n;OfflineCatalogSnapshot t;if(!ok||memcmp(b.data(),"MFOC",4)||!r32(b,x,v)||v!=V||!r32(b,x,n)||n>MAX){if(e)*e="invalid catalog";return false;}while(n--){std::string k;MediaItem i;if(!rst(b,x,k)||!rit(b,x,i)){if(e)*e="invalid catalog";return false;}t.series[k]=std::move(i);}if(!rlist(b,x,t.seasonsBySeries)||!rlist(b,x,t.episodesBySeason)||x!=b.size()){if(e)*e="invalid catalog";return false;}o=std::move(t);return true;}
bool OfflineCatalog::storeSeasons(const std::string&p,const MediaItem&s,const std::vector<MediaItem>&v,std::string*e){return storeDiscoveredHierarchy(p,s,v,{},true,e);}
bool OfflineCatalog::storeEpisodes(const std::string&p,const MediaItem&s,const MediaItem&season,const std::vector<MediaItem>&v,std::string*e){return storeDiscoveredHierarchy(p,s,{season},{{season.id,v}},true,e);}
bool OfflineCatalog::storeDiscoveredHierarchy(const std::string&p,const MediaItem&s,const std::vector<MediaItem>&v,const std::map<std::string,std::vector<MediaItem> >&eps,bool complete,std::string*e){if(!complete)return true;if(s.id.empty()){if(e)*e="missing series id";return false;}std::lock_guard<std::mutex>g(lock);OfflineCatalogSnapshot x;std::string loadError;if(!loadForUpdate(p,x,&loadError)){if(e)*e=loadError;return false;}auto old=x.series.find(s.id);if(old==x.series.end()||!s.title.empty())x.series[s.id]=s;mergeItems(x.seasonsBySeries[s.id],v);for(const auto&a:eps)if(!a.first.empty())mergeItems(x.episodesBySeason[a.first],a.second);return save(p,x,e);}
bool OfflineCatalog::reconcileSeries(const std::string&p,const std::vector<MediaItem>&series,std::string*e){std::lock_guard<std::mutex>g(lock);OfflineCatalogSnapshot x;std::string le;if(!loadForUpdate(p,x,&le)){if(e)*e=le;return false;}std::set<std::string> keep;for(const auto&i:series)if(!i.id.empty())keep.insert(i.id);for(auto it=x.series.begin();it!=x.series.end();)if(!keep.count(it->first))it=x.series.erase(it);else ++it;for(auto it=x.seasonsBySeries.begin();it!=x.seasonsBySeries.end();){if(!keep.count(it->first)){for(const auto&s:it->second)x.episodesBySeason.erase(s.id);it=x.seasonsBySeries.erase(it);}else ++it;}return save(p,x,e);}
std::vector<MediaItem> OfflineCatalog::seasons(const std::string&p,const std::string&id){OfflineCatalogSnapshot x;load(p,x,nullptr);return x.seasonsBySeries[id];} std::vector<MediaItem> OfflineCatalog::episodes(const std::string&p,const std::string&id){OfflineCatalogSnapshot x;load(p,x,nullptr);return x.episodesBySeason[id];}
}
